 <?php if ( get_theme_mod( 'navid_show_journal', true ) ) : $journal = new WP_Query( array( 'post_type' => 'post', 'post_status' => 'publish', 'posts_per_page' => 3, 'no_found_rows' => true, 'ignore_sticky_posts' => true ) ); if ( $journal->have_posts() ) : ?>
 <section class="journal-section container" aria-labelledby="journal-title"><div class="section-heading"><div><span class="eyebrow"><?php esc_html_e( 'کمی بیشتر بدانیم', 'navid-commerce' ); ?></span><h2 id="journal-title"><?php esc_html_e( 'انتخاب بهتر، با مجله نوید', 'navid-commerce' ); ?><span class="heading-dot" aria-hidden="true"></span></h2></div><?php $journal_url = get_permalink( get_option( 'page_for_posts' ) ); if ( $journal_url ) : ?><a class="text-link" href="<?php echo esc_url( $journal_url ); ?>"><?php esc_html_e( 'همه نوشته‌ها', 'navid-commerce' ); ?><?php navid_commerce_icon( 'arrow' ); ?></a><?php endif; ?></div><div class="journal-grid">
 <?php $guide_art = array( 'headphones', 'watch', 'keyboard' ); $guide_index = 0; while ( $journal->have_posts() ) : $journal->the_post(); ?><article class="journal-card"><a href="<?php the_permalink(); ?>" class="journal-cover" tabindex="-1" aria-hidden="true"><?php if ( has_post_thumbnail() ) : the_post_thumbnail( 'medium_large', array( 'loading' => 'lazy', 'alt' => '' ) ); else : ?><img src="<?php echo esc_url( get_theme_file_uri( '/assets/images/' . $guide_art[ $guide_index % 3 ] . '.svg' ) ); ?>" width="380" height="240" alt="" loading="lazy"><?php endif; ?><span><?php esc_html_e( 'مجله نوید', 'navid-commerce' ); ?></span></a><div class="journal-copy"><time datetime="<?php echo esc_attr( get_the_date( 'c' ) ); ?>"><?php echo esc_html( get_the_date() ); ?></time><h3><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h3><a class="text-link" href="<?php the_permalink(); ?>"><?php esc_html_e( 'خواندن نوشته', 'navid-commerce' ); ?><?php navid_commerce_icon( 'arrow' ); ?></a></div></article><?php ++$guide_index; endwhile; wp_reset_postdata(); ?>
 </div></section><?php endif; endif; ?>
